package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbAdjacencyBuildTxnFamilyTest {

	private TripleStore tripleStore;

	@AfterEach
	void tearDown() throws Exception {
		if (tripleStore != null) {
			tripleStore.close();
		}
	}

	@Test
	void scannersReportTheActualExplicitAndInferredPlanes(@TempDir File dataDir) throws Exception {
		tripleStore = new TripleStore(dataDir, new LmdbStoreConfig("spoc,posc"), null);
		tripleStore.startTransaction();
		tripleStore.storeTriple(uri(1), uri(10), uri(100), 0, true);
		tripleStore.storeTriple(uri(2), uri(20), uri(200), 0, false);
		tripleStore.commit();

		try (LmdbAdjacencyBuildTxnFamily family = new LmdbAdjacencyBuildTxnFamily(tripleStore)) {
			assertPlanes(family.scanner(LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT), true, true,
					LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT);
			assertPlanes(family.scanner(LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT), false, true,
					LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT);
			assertPlanes(family.scanner(LmdbReferenceNodeLocator.PLANE_OUTGOING_INFERRED), true, false,
					LmdbReferenceNodeLocator.PLANE_OUTGOING_INFERRED);
			assertPlanes(family.scanner(LmdbReferenceNodeLocator.PLANE_INCOMING_INFERRED), false, false,
					LmdbReferenceNodeLocator.PLANE_INCOMING_INFERRED);
		}
	}

	private static void assertPlanes(AdjacencySourceScanner scanner, boolean outgoing, boolean explicit,
			int expectedPlane) throws Exception {
		List<Integer> planes = new ArrayList<>();
		AdjacencySourceScanner.GroupConsumer consumer = new AdjacencySourceScanner.GroupConsumer() {

			@Override
			public void begin(long key, long predicate, int plane) {
				planes.add(plane);
			}

			@Override
			public void pair(long neighbor, long context) {
			}

			@Override
			public void end() {
			}
		};
		if (outgoing) {
			scanner.scanOutgoing(explicit, consumer);
		} else {
			scanner.scanIncoming(explicit, consumer);
		}
		assertThat(planes).containsOnly(expectedPlane);
	}

	private static long uri(long payload) {
		return ValueIds.createId(ValueIds.T_URI, payload);
	}
}
